<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Image Preview</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f4f7fb;
        --panel: rgba(255, 255, 255, 0.88);
        --panel-strong: #ffffff;
        --text: #172033;
        --muted: #5f6b85;
        --line: rgba(23, 32, 51, 0.12);
        --accent: #3461ff;
        --danger: #d9364c;
        --danger-strong: #b7283a;
        --shadow: 0 24px 60px rgba(23, 32, 51, 0.16);
        --radius-xl: 28px;
        --radius-lg: 20px;
        --radius-md: 14px;
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top, rgba(52, 97, 255, 0.12), transparent 40%),
          linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
        min-height: 100vh;
      }

      main {
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 32px 20px;
      }

      .preview-shell {
        width: min(920px, 100%);
        display: grid;
        gap: 18px;
      }

      .hero {
        display: flex;
        justify-content: space-between;
        gap: 16px;
        align-items: end;
      }

      .eyebrow {
        margin: 0 0 8px;
        text-transform: uppercase;
        letter-spacing: 0.14em;
        font-size: 0.75rem;
        color: var(--muted);
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 4vw, 3.1rem);
        line-height: 1.05;
      }

      .subtitle {
        margin: 10px 0 0;
        max-width: 56ch;
        color: var(--muted);
        font-size: 1rem;
        line-height: 1.6;
      }

      .card {
        background: var(--panel);
        backdrop-filter: blur(16px);
        border: 1px solid var(--line);
        border-radius: var(--radius-xl);
        box-shadow: var(--shadow);
        padding: 22px;
      }

      .image-frame {
        overflow: hidden;
        border-radius: calc(var(--radius-xl) - 8px);
        aspect-ratio: 16 / 9;
        background: linear-gradient(135deg, #dfe8ff, #f8fbff);
        border: 1px solid rgba(23, 32, 51, 0.08);
      }

      .image-frame img {
        width: 100%;
        height: 100%;
        object-fit: cover;
        display: block;
      }

      .image-meta {
        display: flex;
        justify-content: space-between;
        gap: 16px;
        align-items: center;
        margin-top: 18px;
      }

      .meta-copy h2 {
        margin: 0;
        font-size: 1.2rem;
      }

      .meta-copy p {
        margin: 6px 0 0;
        color: var(--muted);
      }

      .trigger,
      .secondary,
      .danger {
        appearance: none;
        border: 0;
        font: inherit;
        border-radius: 999px;
        padding: 0.85rem 1.2rem;
        cursor: pointer;
        transition: transform 0.16s ease, box-shadow 0.16s ease, background-color 0.16s ease;
      }

      .trigger {
        background: var(--danger);
        color: white;
        box-shadow: 0 10px 24px rgba(217, 54, 76, 0.24);
      }

      .trigger:hover,
      .trigger:focus-visible,
      .secondary:hover,
      .secondary:focus-visible,
      .danger:hover,
      .danger:focus-visible {
        transform: translateY(-1px);
      }

      .trigger:hover,
      .trigger:focus-visible {
        background: var(--danger-strong);
      }

      .trigger:focus-visible,
      .secondary:focus-visible,
      .danger:focus-visible {
        outline: 3px solid rgba(52, 97, 255, 0.22);
        outline-offset: 2px;
      }

      .secondary {
        background: #e9eefc;
        color: var(--text);
      }

      .delete-dialog {
        width: min(520px, calc(100vw - 32px));
        border: 1px solid rgba(23, 32, 51, 0.12);
        border-radius: 24px;
        padding: 0;
        box-shadow: 0 32px 80px rgba(23, 32, 51, 0.26);
        background: var(--panel-strong);
      }

      .delete-dialog::backdrop {
        background: rgba(11, 17, 31, 0.48);
        backdrop-filter: blur(4px);
      }

      .dialog-body {
        padding: 24px;
      }

      .dialog-title {
        margin: 0;
        font-size: 1.35rem;
      }

      .dialog-copy {
        margin: 10px 0 0;
        color: var(--muted);
        line-height: 1.6;
      }

      .dialog-actions {
        display: flex;
        justify-content: flex-end;
        gap: 12px;
        margin-top: 24px;
      }

      .danger {
        background: var(--danger);
        color: white;
      }

      .status {
        margin: 0;
        min-height: 1.5em;
        color: var(--muted);
        font-size: 0.95rem;
      }

      @media (max-width: 720px) {
        .hero,
        .image-meta,
        .dialog-actions {
          flex-direction: column;
          align-items: stretch;
        }

        .image-meta {
          align-items: start;
        }

        .dialog-actions {
          margin-top: 18px;
        }
      }
    </style>
  </head>
  <body>
    <main>
      <section class="preview-shell" aria-labelledby="page-title">
        <header class="hero">
          <div>
            <p class="eyebrow">Library preview</p>
            <h1 id="page-title">Review before you remove</h1>
            <p class="subtitle">
              Preview the image below and use the delete button to confirm removal from your library.
            </p>
          </div>
          <p class="status" id="status" aria-live="polite"></p>
        </header>

        <article class="card">
          <div class="image-frame">
            <img
              src="https://images.unsplash.com/photo-1498050108023-c5249f4df085?auto=format&fit=crop&w=1400&q=80"
              alt="A modern workspace with a laptop, notebook, and coffee cup"
            />
          </div>

          <div class="image-meta">
            <div class="meta-copy">
              <h2>Workspace Notes</h2>
              <p>Saved to your library on May 6, 2026</p>
            </div>
            <button class="trigger" type="button" id="open-delete-dialog">Delete image</button>
          </div>
        </article>
      </section>
    </main>

    <dialog class="delete-dialog" id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
      <form method="dialog" class="dialog-body">
        <h2 class="dialog-title" id="dialog-title">Delete this image?</h2>
        <p class="dialog-copy" id="dialog-description">
          This will permanently remove the image from your library. This action cannot be undone.
        </p>

        <div class="dialog-actions">
          <button class="secondary" value="cancel">Cancel</button>
          <button class="danger" id="confirm-delete" value="delete">Delete</button>
        </div>
      </form>
    </dialog>

    <script>
      const dialog = document.getElementById("delete-dialog");
      const openButton = document.getElementById("open-delete-dialog");
      const confirmButton = document.getElementById("confirm-delete");
      const status = document.getElementById("status");
      const card = document.querySelector(".card");

      openButton.addEventListener("click", () => {
        dialog.showModal();
      });

      confirmButton.addEventListener("click", () => {
        status.textContent = "Image deleted from your library.";
        card.style.opacity = "0.45";
        card.style.filter = "grayscale(0.18)";
        openButton.disabled = true;
        openButton.textContent = "Image deleted";
      });

      dialog.addEventListener("close", () => {
        if (dialog.returnValue !== "delete") {
          status.textContent = "";
        }
      });
    </script>
  </body>
</html>
