        color: var(--text);
        background:
          radial-gradient(circle at top, rgba(52, 97, 255, 0.12), transparent 40%),
          linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
        min-height: 100vh;
      }

      main {
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 32px 20px;
      }

      .preview-shell {
        width: min(920px, 100%);
        display: grid;
        gap: 18px;
      }

      .hero {
        display: flex;
        justify-content: space-between;
        gap: 16px;
        align-items: end;
      }

      .eyebrow {
        margin: 0 0 8px;
        text-transform: uppercase;
        letter-spacing: 0.14em;
        font-size: 0.75rem;
        color: var(--muted);
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 4vw, 3.1rem);
        line-height: 1.05;
