      .dialog-title {
        margin: 0;
        font-size: 1.35rem;
      }

      .dialog-copy {
        margin: 10px 0 0;
        color: var(--muted);
        line-height: 1.6;
      }

      .dialog-actions {
        display: flex;
        justify-content: flex-end;
        gap: 12px;
        margin-top: 24px;
      }

      .danger {
        background: var(--danger);
        color: white;
      }

      .status {
        margin: 0;
        min-height: 1.5em;
        color: var(--muted);
        font-size: 0.95rem;
      }

      @media (max-width: 720px) {
        .hero,
